use serde::Deserialize;

#[derive(Debug, Deserialize)]
pub struct Settings {
    pub user_name: String,
    pub retry_count: u32,
    pub timeout_secs: u64,
}

pub fn load(raw: &str) -> serde_json::Result<Settings> {
    serde_json::from_str(raw)
}

